def coulomb_friction_force(mu, normal_force):
    return mu * normal_force






def kinetic_friction(mu_k, normal_force):
    return mu_k * normal_force






def static_friction_max(mu_s, normal_force):
    return mu_s * normal_force






def coefficient_of_friction(friction_force, normal_force):
    return friction_force / normal_force






def hertz_contact_pressure(force, contact_radius):
    return 3.0 * force / (2.0 * math.pi * contact_radius * contact_radius)






def archard_wear_volume(k, load, sliding_distance, hardness):
    return k * load * sliding_distance / hardness






def bearing_pressure(load, projected_area):
    return load / projected_area






def sommerfeld_number(viscosity, speed, load_per_area, clearance_ratio):
    return (viscosity * speed / load_per_area) / (
        clearance_ratio * clearance_ratio
    )






def stribeck_parameter(viscosity, velocity, pressure):
    return viscosity * velocity / pressure






def flash_temperature_rise(mu, load, velocity, thermal_conductivity, contact_length):
    return mu * load * velocity / (thermal_conductivity * contact_length)






def lubrication_film_thickness(viscosity, velocity, load_per_width):
    ratio = viscosity * velocity / load_per_width

    return math.exp(2.0 / 3.0 * math.log(ratio))






def friction_power_loss(friction_force, velocity):
    return friction_force * velocity
